using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using KianaPet;
class ConnectionUiTests {
 static int checks;static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;}static object Field(object value,string name){return value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
 static void Capture(Window w,string name){w.UpdateLayout();var bitmap=new RenderTargetBitmap((int)Math.Ceiling(w.ActualWidth),(int)Math.Ceiling(w.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(w);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(Store.Root,name+".png")))encoder.Save(file);}
 [STAThread]static int Main(string[] args){Store.Root=args[0];Store.Save(new Config{LinkChatGPT=false,MusicEnabled=false,Walking=false,Gravity=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false,NoticeSound=false});var app=new Application{ShutdownMode=ShutdownMode.OnLastWindowClose};var pet=new PetWindow(true);bool passed=false;
  pet.Loaded+=async delegate{try{await Task.Delay(1100);((DispatcherTimer)Field(pet,"animation")).Stop();var settings=app.Windows.OfType<SettingsWindow>().Single();var gpt=(ComboBox)Field(settings,"gptConnection");var music=(ComboBox)Field(settings,"musicConnection");Check(gpt.SelectedIndex==0&&music.SelectedIndex==0,"existing providers remain defaults");gpt.SelectedIndex=1;music.SelectedIndex=1;await Task.Delay(100);Check(pet.Settings.GPTConnectionMode=="hooks"&&pet.Settings.MusicConnectionMode=="system","selectors change independent provider choices");Check(Store.Load().GPTConnectionMode=="hooks"&&Store.Load().MusicConnectionMode=="system","provider choices persist");settings.NavigateCategory("ChatGPT 联动","");settings.UpdateStatus();Capture(settings,"hooks-settings");
   pet.Music.Current=new MusicState{ConnectionSource="system",Connected=true,Playing=true,Id="123",Title="普通启动的歌曲",Artist="测试歌手",HasPosition=false,HasDuration=true,Duration=240};settings.NavigateCategory("音乐","");settings.UpdateStatus();Check(!((Button)Field(settings,"chorusStart")).IsEnabled&&!((Button)Field(settings,"chorusEnd")).IsEnabled,"missing position disables current-position marking");Check(((ComboBox)Field(settings,"songNormalAction")).IsEnabled,"known song ID still permits normal listening preference");Check(pet.MusicReactionStatus.Contains("没有进度"),"music settings explain chorus limitation");Capture(settings,"system-music-settings");
   var before=MusicReactions.Preference(pet.Settings,"123");pet.MarkMusicChorus(false);Check(ReferenceEquals(before,MusicReactions.Preference(pet.Settings,"123")),"programmatic marking cannot create fake zero-based chorus");
   pet.Settings.LinkChatGPT=true;pet.Link.Current=new BridgeState{ConnectionSource="hooks",AppOpen=true,Connected=true,CanOpenTasks=false,CanNotifications=true,NotificationSource="hooks",NotificationCount=2,At=DateTime.UtcNow,Notices=new[]{new BridgeNotice{Id="ended",Title="本地任务 · 回合结束",State="review"},new BridgeNotice{Id="unknown",Title="本地任务 · 状态待确认",State="unknown"}}};var rows=NoticePreviewRows.Read(pet);Check(rows.Length==2&&rows.All(r=>!r.CanOpen)&&rows.Single(r=>r.Id=="ended").State=="review","Hooks cards retain honest terminal meaning and disable unavailable jumps");Check(rows.Single(r=>r.Id=="unknown").Group==0,"uncertainty receives attention instead of a completed group");pet.OpenNoticeCenter();await Task.Delay(100);var center=app.Windows.OfType<NoticeCenter>().Single();Capture(center,"hooks-notices");passed=true;
  }catch(Exception e){Store.Atomic("ui-error.json",new{error=e.ToString()});}finally{Store.Atomic("ui-result.json",new{passed,checks});foreach(var w in app.Windows.Cast<Window>().Where(w=>w!=pet).ToArray())w.Close();pet.Close();}};app.Run(pet);return passed?0:1;
 }
}
